PRAGMA foreign_keys = ON;
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE TABLE workspace_members (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('OWNER','OPERATOR','VIEWER')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE auth_attempts (id TEXT PRIMARY KEY, bucket TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX idx_auth_attempts ON auth_attempts(bucket,created_at);
CREATE TABLE providers (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), kind TEXT NOT NULL, status TEXT NOT NULL, credential_cipher TEXT, updated_at INTEGER NOT NULL, UNIQUE(workspace_id,kind));
CREATE TABLE sources (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), type TEXT NOT NULL, name TEXT NOT NULL, last_run_at INTEGER, UNIQUE(workspace_id,type));
CREATE TABLE signals (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), source_id TEXT NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, url TEXT NOT NULL, author TEXT, published_at TEXT, captured_at INTEGER NOT NULL, raw_text TEXT NOT NULL, normalized_text TEXT NOT NULL, metadata TEXT NOT NULL, fingerprint TEXT NOT NULL, UNIQUE(workspace_id,external_id), UNIQUE(workspace_id,fingerprint));
CREATE TABLE opportunities (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), signal_id TEXT NOT NULL REFERENCES signals(id), title TEXT NOT NULL, problem TEXT NOT NULL, desired_outcome TEXT NOT NULL, intent TEXT NOT NULL, urgency TEXT NOT NULL, budget_signal TEXT NOT NULL, confidence INTEGER NOT NULL, opportunity_score INTEGER NOT NULL, recommended_action TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'NEW', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, UNIQUE(workspace_id,signal_id));
CREATE INDEX idx_opportunity_feed ON opportunities(workspace_id,status,opportunity_score DESC);
CREATE TABLE opportunity_scores (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), opportunity_id TEXT NOT NULL REFERENCES opportunities(id), version TEXT NOT NULL, components TEXT NOT NULL, total INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE executions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), opportunity_id TEXT NOT NULL REFERENCES opportunities(id), template TEXT NOT NULL, blueprint TEXT NOT NULL, status TEXT NOT NULL, validation TEXT, demo_token TEXT UNIQUE, demo_url TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE execution_artifacts (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), execution_id TEXT NOT NULL REFERENCES executions(id), type TEXT NOT NULL, content TEXT NOT NULL, checksum TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(execution_id,type));
CREATE TABLE distributions (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), opportunity_id TEXT NOT NULL REFERENCES opportunities(id), execution_id TEXT NOT NULL REFERENCES executions(id), target TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL, approved_by TEXT REFERENCES users(id), approved_at INTEGER, contacted_at INTEGER, contact_reference TEXT, next_follow_up_at TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX idx_followup ON distributions(workspace_id,status,next_follow_up_at);
CREATE TABLE outcomes (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), distribution_id TEXT NOT NULL REFERENCES distributions(id), state TEXT NOT NULL, revenue_minor INTEGER NOT NULL DEFAULT 0 CHECK(revenue_minor>=0), currency TEXT NOT NULL DEFAULT 'IDR', loss_reason TEXT, feedback TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL);
CREATE INDEX idx_outcomes ON outcomes(workspace_id,distribution_id,created_at);
CREATE TABLE usage_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), provider TEXT NOT NULL, operation TEXT NOT NULL, units INTEGER NOT NULL, estimated_cost REAL, job_id TEXT, created_at INTEGER NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL REFERENCES users(id), operation TEXT NOT NULL, target_id TEXT NOT NULL, request_id TEXT NOT NULL, detail TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX idx_audit ON audit_events(workspace_id,created_at DESC);
CREATE TABLE jobs (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL REFERENCES users(id), type TEXT NOT NULL, input TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL DEFAULT 3, next_run_at INTEGER NOT NULL, lease_until INTEGER, error_code TEXT, error_message TEXT, result TEXT, idempotency_key TEXT NOT NULL, request_id TEXT NOT NULL, created_at INTEGER NOT NULL, finished_at INTEGER, UNIQUE(workspace_id,idempotency_key));
CREATE INDEX idx_jobs ON jobs(workspace_id,status,next_run_at);
CREATE TABLE settings (workspace_id TEXT NOT NULL REFERENCES workspaces(id), key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(workspace_id,key));
